/**
 * Option B for walnut-net on a machine with two Walnuts (service sets): a later Walnut's set runs a
 * walnut-net of its own, with its own key, address, config, control socket and UDP port, inside its
 * set; the machine's (the default set's) is left exactly as it is.
 *
 *  1. Under one HOME the default runtime and a set's compute disjoint net state dirs, keys, control
 *     sockets and port files; the default's is today's path.
 *  2. A machine with one Walnut writes the config Walnut wrote before sets, byte for byte (the text
 *     was generated by the net-core.ts of main before sets).
 *  3. A set's supervisor never writes the default's files.
 *  4. `walnut daemon net-id` (service-set-net.ts) configures the set's own daemon over its loopback
 *     door, only when that daemon's hello names the set; `net-forget` takes one entry off the
 *     default's list and nothing else.
 *  5. With the real walnut-net (the published build the host downloads, WALNUT_NET_TEST_PUBLISHED_BIN, or
 *     WALNUT_NET_TEST_BIN, or a local build), the default's runs and our set's starts beside it: the
 *     ports differ, the default is never restarted and its config never changes, and a leader
 *     reaches each daemon through its own endpoint.
 */
import { afterAll, afterEach, describe, expect, it } from 'vitest'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import net from 'node:net'
import { EventEmitter } from 'node:events'
import { PassThrough } from 'node:stream'
import { spawn as realSpawn, type ChildProcess } from 'node:child_process'
import { WebSocketServer } from 'ws'
import { createNetSupervisor, type NetDeps, type NetSupervisor } from '../../src/providers/net-core.js'
import { netStateDir, netStateDirOf } from '../../src/providers/net-config-core.js'
import { netControlPath } from '../../src/providers/net-control.js'
import { decodeNetRequest, encodeNetRequest, forgetDefaultNetMember, serviceSetNetId } from '../../src/providers/service-set-net.js'
import { serviceSet, serviceSetBase } from '../../src/providers/service-set.js'
import { netKey } from '../helpers/net-keys.js'

const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'wn-set-net-')))
afterAll(() => { if (root.includes('wn-set-net-')) fs.rmSync(root, { recursive: true, force: true }) })

const WALNUT = '0123456789abcdef0123456789abcdef'
const SET = '0123456789abcdef'
const SELF = netKey('set-net-self')
const macA = { id: netKey('set-net-mac-a'), name: 'mac-a', accept: true }
const boxA = { id: netKey('set-net-box-a'), name: 'box-a', accept: false, addrs: ['10.0.0.2:4100'] }

let open: NetSupervisor[] = []
afterEach(async () => {
  for (const s of open) await s.stop()
  open = []
})

/** The service's net state dir under `home`, as the daemon computes it (net-config-core.ts). */
const dirOf = (home: string, setId = '') => netStateDir({ serviceStateDir: '/state', prodDaemon: false, daemonDir: '/rt', home, setId })

describe('a set has its own network identity', () => {
  it('the default keeps today\'s dir; a set\'s key, config, control socket and port file are its own, under one HOME', () => {
    const home = path.join(root, 'h1')
    const def = dirOf(home)
    const set = dirOf(home, SET)
    expect(def).toBe(path.join(home, '.local', 'state', 'open-walnut', 'net'))
    expect(netStateDir({ serviceStateDir: null, prodDaemon: true, daemonDir: '/rt', home })).toBe(def)
    expect(set).toBe(path.join(serviceSetBase(home, SET), 'net'))
    // netStateDirOf (the path join passed in) keeps the same rule.
    expect(netStateDirOf({ serviceStateDir: '/state', prodDaemon: false, daemonDir: '/rt', home, setId: SET, join: path.join })).toBe(set)
    // Only a service runs in a set; anything else keeps today's rule.
    expect(netStateDir({ serviceStateDir: null, prodDaemon: false, daemonDir: '/rt', home, setId: SET })).toBe('/rt/net')
    expect(netStateDir({ serviceStateDir: '/state', prodDaemon: false, daemonDir: '/rt', home, setId: 'not-a-set' })).toBe(def)
    const files = (d: string) => [d, path.join(d, 'net.key'), `${path.join(d, 'net.key')}.port`, path.join(d, 'config.json'), netControlPath(d)]
    const a = files(def)
    const b = files(set)
    for (const f of b) expect(a).not.toContain(f)
    expect(path.relative(def, set).startsWith('..')).toBe(true)
  })

  it('a home too long for the socket path gives each its own fallback socket', () => {
    const home = path.join(root, 'x'.repeat(70))
    const a = netControlPath(dirOf(home))
    const b = netControlPath(dirOf(home, SET))
    expect(a.startsWith('/tmp/walnut-net-')).toBe(true)
    expect(b.startsWith('/tmp/walnut-net-')).toBe(true)
    expect(a).not.toBe(b)
  })
})

/** A stand-in for walnut-net: `id` prints the key's id; `run` answers status and reload on the control socket. */
function fakeNet(self = SELF) {
  const seen = { runs: 0, reloads: 0 }
  const spawn: NetDeps['spawn'] = (_cmd, args) => {
    const p = new EventEmitter() as ChildProcess
    const stdout = new PassThrough()
    Object.assign(p, { stdout, stderr: new PassThrough(), stdin: new PassThrough(), pid: 40000 + seen.runs })
    if (args[0] === 'id') {
      setTimeout(() => stdout.write(JSON.stringify({ id: self }) + '\n'), 1)
      setTimeout(() => p.emit('exit', 0, null), 20)
      return p
    }
    seen.runs++
    const cfg = JSON.parse(fs.readFileSync(args[2]!, 'utf8')) as { control: string }
    const server = net.createServer((sock) => {
      sock.setEncoding('utf8')
      sock.on('data', (d: string) => {
        const req = JSON.parse(d.slice(0, d.indexOf('\n'))) as { op: string }
        if (req.op === 'reload') seen.reloads++
        sock.end(JSON.stringify(req.op === 'reload' ? { ok: true, restart: false } : { ok: true, peers: [] }) + '\n')
      })
    })
    let alive = true
    Object.assign(p, {
      kill: (sig?: string) => {
        if (alive) { alive = false; server.close(); fs.rmSync(cfg.control, { force: true }); setTimeout(() => p.emit('exit', null, sig ?? 'SIGTERM'), 5) }
        return true
      },
    })
    server.listen(cfg.control, () => stdout.write(JSON.stringify({ event: 'ready', id: self, protocol: 2 }) + '\n'))
    return p
  }
  return { spawn, seen }
}

function supervisor(stateDir: string, portFile: string, spawn: NetDeps['spawn'], bin = '/fake/walnut-net') {
  fs.mkdirSync(path.dirname(portFile), { recursive: true })
  if (!fs.existsSync(portFile)) fs.writeFileSync(portFile, '1\n')
  const s = createNetSupervisor({ spawn, stateDir, portFile, bin: () => bin })
  open.push(s)
  return s
}

/** Every file under `dir` with its bytes and mtime: what "never written" is checked against. */
function snapshot(dir: string): Record<string, string> {
  const out: Record<string, string> = {}
  const walk = (d: string) => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const f = path.join(d, e.name)
      if (e.isDirectory()) walk(f)
      else if (e.isFile()) out[f] = `${fs.statSync(f).mtimeMs}:${fs.readFileSync(f, 'base64')}`
    }
  }
  if (fs.existsSync(dir)) walk(dir)
  return out
}

describe('the default set alone, and a set beside it', () => {
  it('a machine with one Walnut writes the text Walnut wrote before sets', async () => {
    const home = path.join(root, 'snap')
    const stateDir = dirOf(home)
    const portFile = path.join(home, 'rt', 'daemon.port')
    const s = supervisor(stateDir, portFile, fakeNet().spawn)
    const self = { id: SELF, name: 'me', accept: false }
    await s.configure({ relayMode: 'public', members: [macA, boxA, self] })
    await s.configure({ relayMode: 'public', members: [boxA, { ...macA, relays: ['https://relay.example.test'] }] })
    const text = fs.readFileSync(path.join(stateDir, 'config.json'), 'utf8').split(stateDir).join('<net>').split(portFile).join('<port>')
    expect(text).toBe(`{
  "version": 1,
  "key": "<net>/net.key",
  "relayMode": "public",
  "relays": [],
  "relayRoots": [],
  "members": [
    {
      "id": "${boxA.id}",
      "name": "box-a",
      "accept": false,
      "addrs": [
        "10.0.0.2:4100"
      ]
    },
    {
      "id": "${macA.id}",
      "name": "mac-a",
      "accept": true,
      "relays": [
        "https://relay.example.test"
      ]
    }
  ],
  "daemonPortFile": "<port>",
  "control": "<net>/ctl.sock"
}
`)
    expect(netControlPath(stateDir)).toBe(path.join(stateDir, 'ctl.sock'))
  })

  it('a set\'s supervisor writes only inside its set: the default\'s files are never touched', async () => {
    const home = path.join(root, 'beside')
    const def = supervisor(dirOf(home), path.join(home, 'rt-default', 'daemon.port'), fakeNet(netKey('set-net-default')).spawn)
    await def.configure({ relayMode: 'public', members: [macA] })
    const before = snapshot(dirOf(home))
    expect(Object.keys(before).length).toBeGreaterThan(0)
    const setFake = fakeNet(netKey('set-net-set'))
    const set = supervisor(dirOf(home, SET), path.join(home, 'rt-set', 'daemon.port'), setFake.spawn)
    const r = await set.configure({ relayMode: 'public', members: [{ ...macA }] })
    expect(r).toEqual({ endpointId: netKey('set-net-set'), running: true })
    await set.configure({ enabled: false })
    expect(snapshot(dirOf(home))).toEqual(before)
    expect(fs.existsSync(path.join(dirOf(home, SET), 'net.key.port'))).toBe(false)
  })
})

describe('walnut daemon net-id and net-forget (host side)', () => {
  /** A fake set daemon on its loopback door: answers hello, net.configure and net.status, and keeps what it was sent. */
  // A uid of each home's own: a home this long puts the set's runtime dir in /tmp/open-walnut-set-<uid>-<id16>.
  let uid = 970_000 + (process.pid % 1000) * 10
  const uids = new Map<string, number>()
  const uidOf = (home: string) => { if (!uids.has(home)) uids.set(home, uid++); return uids.get(home)! }
  afterAll(() => { for (const u of uids.values()) fs.rmSync(`/tmp/open-walnut-set-${u}-${SET}`, { recursive: true, force: true }) })
  async function setDaemon(home: string, hello: Record<string, unknown>, o: { silent?: string } = {}) {
    const set = serviceSet('linux', home, SET, { uid: uidOf(home) })
    fs.mkdirSync(set.installRoot, { recursive: true })
    fs.writeFileSync(path.join(set.installRoot, 'walnut-launcher.sh'), '#!/bin/sh\n')
    fs.mkdirSync(set.runtimeDir, { recursive: true })
    const got: Array<Record<string, unknown>> = []
    const wss = new WebSocketServer({ port: 0, host: '127.0.0.1' })
    await new Promise<void>((r) => wss.once('listening', () => r()))
    wss.on('connection', (ws) => ws.on('message', (raw) => {
      const m = JSON.parse(raw.toString()) as Record<string, unknown>
      got.push(m)
      if (m.cmd === o.silent) return
      const answer = m.cmd === 'hello' ? { ok: true, ...hello }
        : m.cmd === 'net.configure' ? { ok: true, endpointId: netKey('set-net-set'), running: true }
          : { ok: true, running: true, node: { addrs: ['192.168.1.9:50123'] } }
      ws.send(JSON.stringify({ id: m.id, ...answer }))
    }))
    fs.writeFileSync(path.join(set.runtimeDir, 'daemon.port'), `${(wss.address() as net.AddressInfo).port}\n`)
    return { got, close: () => new Promise<void>((r) => wss.close(() => r())) }
  }
  const request = { relayMode: 'public', relays: [], relayRoots: [], members: [{ id: macA.id, name: 'mac-a', accept: true }] }
  const input = (home: string) => ({ walnutId: WALNUT, request, home, uid: uidOf(home), platform: 'linux' as const, defaultRuntimeDir: path.join(home, 'default-rt'), doorWaitMs: 200, netWaitMs: 2_000 })

  it('net-id: the set\'s own daemon takes the leader\'s list and answers its endpoint id and addresses', async () => {
    const home = path.join(root, 'netid')
    const d = await setDaemon(home, { serviceSet: SET })
    try {
      const { set, answer } = await serviceSetNetId(input(home))
      expect(set).toBe(SET)
      expect(answer).toEqual({ ok: true, endpointId: netKey('set-net-set'), addrs: ['192.168.1.9:50123'] })
      expect(d.got.map((m) => m.cmd)).toEqual(['hello', 'net.configure', 'net.status'])
      expect(d.got[1]).toMatchObject({ relayMode: 'public', members: request.members })
      // The machine's own net state is never touched.
      expect(fs.existsSync(dirOf(home))).toBe(false)
    } finally { await d.close() }
  })

  it('net-id: a daemon whose hello names no set (the machine\'s default, maybe another Walnut\'s) is never configured', async () => {
    const home = path.join(root, 'netid-default')
    const d = await setDaemon(home, {})
    try {
      const { answer } = await serviceSetNetId(input(home))
      expect(answer).toMatchObject({ ok: false, code: 'not_set_daemon' })
      // Asked its hello only: no configure ever reaches it.
      expect(d.got.map((m) => m.cmd)).toEqual(['hello'])
    } finally { await d.close() }
  })

  it('net-id: no own set installed (this Walnut holds the default) or no daemon running: nothing is asked', async () => {
    const free = path.join(root, 'netid-free')
    fs.mkdirSync(free, { recursive: true })
    expect((await serviceSetNetId(input(free))).answer).toMatchObject({ ok: false, code: 'default_set' })
    const down = path.join(root, 'netid-down')
    const set = serviceSet('linux', down, SET, { uid: uidOf(down) })
    fs.mkdirSync(set.installRoot, { recursive: true })
    fs.writeFileSync(path.join(set.installRoot, 'walnut-launcher.sh'), '#!/bin/sh\n')
    expect((await serviceSetNetId(input(down))).answer).toMatchObject({ ok: false, code: 'not_running' })
  })

  it('the request carries a list that lets the leader in, never an off switch', () => {
    expect(decodeNetRequest(encodeNetRequest(request))).toEqual(request)
    expect(decodeNetRequest(encodeNetRequest({ enabled: false, members: request.members }))).toBe(null)
    expect(decodeNetRequest(encodeNetRequest({ members: [{ id: macA.id, name: 'x', accept: false }] }))).toBe(null)
    expect(decodeNetRequest('not base64 !')).toBe(null)
  })

  it('net-forget: only the leader\'s own entry leaves the default\'s list, and the running walnut-net reloads', async () => {
    const home = path.join(root, 'forget')
    const dir = dirOf(home)
    fs.mkdirSync(dir, { recursive: true })
    const other = { id: netKey('set-net-other-mac'), name: 'other-mac', accept: true }
    const control = path.join(dir, 'ctl.sock')
    const cfg = { version: 1, key: path.join(dir, 'net.key'), relays: ['https://relay.other.test'], relayRoots: [], members: [other, macA, boxA], daemonPortFile: '/tmp/open-walnut/daemon.port', control }
    fs.writeFileSync(path.join(dir, 'config.json'), JSON.stringify(cfg, null, 2) + '\n')
    fs.writeFileSync(path.join(dir, 'net.key'), 'secret')
    let reloads = 0
    let refuse = false
    const server = net.createServer((sock) => sock.on('data', () => { reloads++; sock.end(JSON.stringify(refuse ? { ok: false, error: 'invalid' } : { ok: true, restart: false }) + '\n') }))
    await new Promise<void>((r) => server.listen(control, () => r()))
    try {
      expect(await forgetDefaultNetMember(macA.id, home)).toEqual({ ok: true, changed: true, reloaded: true })
      expect(JSON.parse(fs.readFileSync(path.join(dir, 'config.json'), 'utf8'))).toEqual({ ...cfg, members: [other, boxA] })
      expect(fs.readFileSync(path.join(dir, 'net.key'), 'utf8')).toBe('secret')
      expect(reloads).toBe(1)
      // Not on the list (any more): nothing is written and nothing reloads.
      const before = snapshot(dir)
      expect(await forgetDefaultNetMember(macA.id, home)).toEqual({ ok: true, changed: false })
      expect(snapshot(dir)).toEqual(before)
      expect(reloads).toBe(1)
      // A refused reload puts the file back as the running walnut-net has it.
      refuse = true
      const text = fs.readFileSync(path.join(dir, 'config.json'), 'utf8')
      expect(await forgetDefaultNetMember(other.id, home)).toMatchObject({ ok: false, code: 'reload_refused' })
      expect(fs.readFileSync(path.join(dir, 'config.json'), 'utf8')).toBe(text)
    } finally { await new Promise<void>((r) => server.close(() => r())) }
    expect(await forgetDefaultNetMember('nope', home)).toMatchObject({ ok: false, code: 'bad_member' })
    expect(await forgetDefaultNetMember(macA.id, path.join(root, 'no-net'))).toEqual({ ok: true, changed: false })
  })

  /** The default's net dir under a fresh home, with `members` on its list and no walnut-net running. */
  function defaultNet(name: string, members: unknown[]) {
    const home = path.join(root, name)
    const dir = dirOf(home)
    fs.mkdirSync(dir, { recursive: true })
    const cfg = { version: 1, key: path.join(dir, 'net.key'), relays: [], relayRoots: [], members, control: path.join(dir, 'none.sock') }
    fs.writeFileSync(path.join(dir, 'config.json'), JSON.stringify(cfg, null, 2) + '\n')
    return { home, dir, cfg, file: path.join(dir, 'config.json') }
  }

  it('N-L1: a write by the other Walnut\'s supervisor between the read and the rename is kept (read again, then retried)', async () => {
    const other = { id: netKey('set-net-other-mac'), name: 'other-mac', accept: true }
    const newcomer = { id: netKey('set-net-newcomer'), name: 'newcomer', accept: false }
    const n = defaultNet('forget-race', [other, macA, boxA])
    const answer = await forgetDefaultNetMember(macA.id, n.home, {
      beforeReplace: (attempt) => { if (attempt === 0) fs.writeFileSync(n.file, JSON.stringify({ ...n.cfg, members: [other, macA, boxA, newcomer] }, null, 2) + '\n') },
    })
    expect(answer).toMatchObject({ ok: true, changed: true })
    expect((JSON.parse(fs.readFileSync(n.file, 'utf8')) as { members: unknown[] }).members).toEqual([other, boxA, newcomer])
  })

  it('N-L2: the last config the default\'s walnut-net came up on loses the entry too (its roll back never puts it back)', async () => {
    const other = { id: netKey('set-net-other-mac'), name: 'other-mac', accept: true }
    const n = defaultNet('forget-good', [other, macA])
    const good = path.join(n.dir, 'config.last-good.json')
    fs.writeFileSync(good, JSON.stringify({ ...n.cfg, members: [other, macA] }, null, 2) + '\n')
    expect(await forgetDefaultNetMember(macA.id, n.home)).toMatchObject({ ok: true, changed: true })
    expect((JSON.parse(fs.readFileSync(good, 'utf8')) as { members: unknown[] }).members).toEqual([other])
    // A last-good without the entry is never written.
    const n2 = defaultNet('forget-good-2', [other, macA])
    fs.writeFileSync(path.join(n2.dir, 'config.last-good.json'), JSON.stringify({ ...n2.cfg, members: [other] }))
    const kept = snapshot(n2.dir)[path.join(n2.dir, 'config.last-good.json')]
    expect(await forgetDefaultNetMember(macA.id, n2.home)).toMatchObject({ ok: true, changed: true })
    expect(snapshot(n2.dir)[path.join(n2.dir, 'config.last-good.json')]).toBe(kept)
  })

  it('N-L6: a `cmd` key in the leader\'s request never changes the command the set\'s daemon is sent', async () => {
    const home = path.join(root, 'netid-cmd')
    const d = await setDaemon(home, { serviceSet: SET })
    try {
      await serviceSetNetId({ ...input(home), request: { ...request, cmd: 'hello' } })
      expect(d.got.map((m) => m.cmd)).toEqual(['hello', 'net.configure', 'net.status'])
    } finally { await d.close() }
  })

  it('N-L4: the host side ends within one budget the leader still waits for', async () => {
    const { NET_ID_BUDGET_MS } = await import('../../src/providers/service-set-net.js')
    const { NET_ID_TIMEOUT_MS } = await import('../../src/providers/service-set-net-pair.js')
    // The leader waits past the host's whole budget plus the line's own start (an upload is before it).
    expect(NET_ID_TIMEOUT_MS).toBeGreaterThanOrEqual(NET_ID_BUDGET_MS + 15_000)
    const home = path.join(root, 'netid-slow')
    const d = await setDaemon(home, { serviceSet: SET }, { silent: 'net.configure' })
    try {
      const started = Date.now()
      const { answer } = await serviceSetNetId({ ...input(home), budgetMs: 600 })
      expect(answer).toMatchObject({ ok: false })
      expect(Date.now() - started).toBeLessThan(4_000)
    } finally { await d.close() }
  })
})

// The real walnut-net: the published build the host downloads (WALNUT_NET_TEST_PUBLISHED_BIN), else WALNUT_NET_TEST_BIN or a local build.
const REAL_BIN = (() => {
  for (const env of [process.env.WALNUT_NET_TEST_PUBLISHED_BIN, process.env.WALNUT_NET_TEST_BIN]) if (env && fs.existsSync(env)) return env
  const built = path.resolve(__dirname, `../../dist/daemon-binaries/walnut-net-${process.platform}-${process.arch}`)
  return fs.existsSync(built) ? built : null
})()

async function until<T>(fn: () => Promise<T | null | undefined | false>, ms: number, what: string): Promise<T> {
  const end = Date.now() + ms
  for (;;) {
    const v = await fn()
    if (v) return v as T
    if (Date.now() >= end) throw new Error(`timed out waiting for ${what}`)
    await new Promise((r) => setTimeout(r, 200))
  }
}

/** A daemon's door stand-in: every connection hears `name`. */
async function door(portFile: string, name: string): Promise<net.Server> {
  const server = net.createServer((sock) => sock.end(name))
  await new Promise<void>((r) => server.listen(0, '127.0.0.1', () => r()))
  fs.mkdirSync(path.dirname(portFile), { recursive: true })
  fs.writeFileSync(portFile, `${(server.address() as net.AddressInfo).port}\n`)
  return server
}

const read = (port: number) => new Promise<string>((resolve, reject) => {
  // A stream opens on its first bytes (QUIC): say something, as a daemon link's hello does.
  const sock = net.createConnection(port, '127.0.0.1', () => sock.write('hi\n'))
  let got = ''
  sock.setEncoding('utf8')
  sock.on('data', (d: string) => { got += d })
  sock.on('end', () => resolve(got))
  sock.on('error', reject)
  setTimeout(() => { sock.destroy(); resolve(got) }, 15_000)
})

describe.skipIf(!REAL_BIN)('the real walnut-net: the default\'s runs, our set\'s starts beside it', () => {
  it('ports do not collide, the default is never restarted and its config never changes, and a leader reaches each daemon by its own endpoint', async () => {
    const spawn: NetDeps['spawn'] = (cmd, args, o) => realSpawn(cmd, args, o)
    const home = path.join(root, 'real')
    const servers: net.Server[] = []
    try {
      servers.push(await door(path.join(home, 'rt-default', 'daemon.port'), 'default-daemon'))
      servers.push(await door(path.join(home, 'rt-set', 'daemon.port'), 'set-daemon'))
      const mac = supervisor(path.join(home, 'mac-net'), path.join(home, 'mac-rt', 'daemon.port'), spawn, REAL_BIN!)
      const macId = await mac.identity()
      // The other Walnut's daemon runs the machine's walnut-net (the default set), letting its own Mac and ours in.
      const def = supervisor(dirOf(home), path.join(home, 'rt-default', 'daemon.port'), spawn, REAL_BIN!)
      const defId = (await def.configure({ relayMode: 'none', members: [{ id: macId, name: 'mac', accept: true }, { id: netKey('real-other-mac'), name: 'other-mac', accept: true }] })).endpointId
      const defStatus = await until(async () => { const st = await def.status(); return st.running ? st : null }, 20_000, 'the default walnut-net')
      const defConfig = fs.readFileSync(path.join(dirOf(home), 'config.json'), 'utf8')
      const defPort = Number(fs.readFileSync(path.join(dirOf(home), 'net.key.port'), 'utf8'))
      // Our set's own, beside it.
      const set = supervisor(dirOf(home, SET), path.join(home, 'rt-set', 'daemon.port'), spawn, REAL_BIN!)
      const setId = (await set.configure({ relayMode: 'none', members: [{ id: macId, name: 'mac', accept: true }] })).endpointId
      await until(async () => (await set.status()).running, 20_000, 'the set\'s walnut-net')
      const setPort = Number(fs.readFileSync(path.join(dirOf(home, SET), 'net.key.port'), 'utf8'))
      expect(setId).not.toBe(defId)
      expect(setPort).not.toBe(defPort)
      expect(set.controlPath).not.toBe(def.controlPath)
      // The leader dials each by its own endpoint (no relay: the addresses each says it has).
      const addrsOf = async (s: NetSupervisor) => (((await s.status()).node?.addrs ?? []) as string[]).filter((a) => !a.startsWith('['))
      const defAddrs = await addrsOf(def)
      const setAddrs = await addrsOf(set)
      expect(defAddrs.every((a) => a.endsWith(`:${defPort}`))).toBe(true)
      expect(setAddrs.every((a) => a.endsWith(`:${setPort}`))).toBe(true)
      await mac.configure({ relayMode: 'none', members: [
        { id: defId, name: 'default', accept: false, addrs: defAddrs },
        { id: setId, name: 'set', accept: false, addrs: setAddrs },
      ] })
      expect(await read((await mac.forward({ to: setId })).port)).toBe('set-daemon')
      expect(await read((await mac.forward({ to: defId })).port)).toBe('default-daemon')
      // The machine's walnut-net: same process, never restarted, same config.
      const after = await def.status()
      expect(after.pid).toBe(defStatus.pid)
      expect(after.restarts).toBe(0)
      expect(fs.readFileSync(path.join(dirOf(home), 'config.json'), 'utf8')).toBe(defConfig)
    } finally {
      for (const s of servers) s.close()
    }
  }, 90_000)
})

describe('the leader\'s own walnut-net list (core/net/net-service-sets.ts)', () => {
  it('adds each paired set endpoint as a member it dials and drops a moved host\'s shared endpoint', async () => {
    const { withServiceSetMembers } = await import('../../src/core/net/net-service-sets.js')
    const shared = netKey('leader-shared')
    const own = netKey('leader-set')
    const cfg = { relayMode: 'public', relays: [], relayRoots: [], members: [{ id: shared, name: 'box', accept: false }, { id: boxA.id, name: 'box-a', accept: false }] }
    // Nothing paired: the very same object, so a machine with one Walnut sends what it sent before.
    expect(withServiceSetMembers(cfg, { add: [], drop: new Set() })).toBe(cfg)
    const set = { id: own, name: 'box-set', accept: false as const, addrs: ['10.0.0.9:5000'] }
    expect(withServiceSetMembers(cfg, { add: [set], drop: new Set() }).members).toEqual([...cfg.members, set])
    expect(withServiceSetMembers(cfg, { add: [set], drop: new Set([shared]) }).members).toEqual([cfg.members[1], set])
  })

  it('reads the paired sets from the host records, by place', async () => {
    const dir = fs.mkdtempSync(path.join(root, 'records-'))
    const saved = process.env.WALNUT_SERVICE_SET_FILE
    process.env.WALNUT_SERVICE_SET_FILE = path.join(dir, 'sets.json')
    try {
      const { hostServiceSets, markServiceSetNetPaired, markServiceSetMoved, serviceSetNetMembers, setNetMemberName } = await import('../../src/providers/service-set-leader.js')
      const own = netKey('records-set')
      const shared = netKey('records-shared')
      await hostServiceSets.write('net:box', { at: Date.now(), set: SET })
      await hostServiceSets.write('ssh:other', { at: Date.now(), set: SET })
      expect(await serviceSetNetMembers()).toEqual({ add: [], drop: new Set(), gone: [] })
      expect(await markServiceSetNetPaired('net:box', SET, { endpoint: own, addrs: ['10.0.0.9:5000'], shared })).toBe(true)
      expect(await serviceSetNetMembers()).toEqual({ add: [{ id: own, name: 'box-set', accept: false, addrs: ['10.0.0.9:5000'] }], drop: new Set(), gone: [] })
      await markServiceSetMoved('net:box', SET)
      expect((await serviceSetNetMembers()).drop).toEqual(new Set([shared]))
      expect(setNetMemberName('net:my host/1')).toBe('my-host-1-set')
      expect(await markServiceSetNetPaired('net:box', 'fedcba9876543210', { endpoint: own, addrs: [], shared })).toBe(false)
    } finally {
      if (saved === undefined) delete process.env.WALNUT_SERVICE_SET_FILE
      else process.env.WALNUT_SERVICE_SET_FILE = saved
    }
  })
})
